def main():
    n = int(input())
    beans_by_color = {}
    for i in range(n):
        a, c = map(int, input().split())
        if c in beans_by_color:
            beans_by_color[c].append(a)
        else:
            beans_by_color[c] = [a]

    best_color = -1
    max_min_deliciousness = 0
    for color in beans_by_color:
        min_deliciousness = min(beans_by_color[color])
        if min_deliciousness > max_min_deliciousness:
            best_color = color
            max_min_deliciousness = min_deliciousness
    print(best_color)
